  return (
    <Modal open={open} onClose={onClose} className="pdf-preview-modal">
      {isContentLoading ? (
        <div className="pdf-preview-loading">decrypting...</div>
      ) : error ? (
        <div className="pdf-preview-error">
          {'> '}
          {error}
        </div>
      ) : (
        <>
          {/* Toolbar */}
          <div className="pdf-toolbar">
            <div className="pdf-toolbar-left">
              <span className="pdf-tag">PDF</span>
              <span className="pdf-filename">{item.name}</span>
            </div>
            <div className="pdf-toolbar-right">
              <button
                type="button"
                className="pdf-btn"
                onClick={handleZoomOut}
                disabled={zoom <= MIN_ZOOM}
                aria-label="Zoom out"
              >
                [-]
              </button>
              <span className="pdf-zoom-display">{zoomPercent}%</span>
              <button
                type="button"
                className="pdf-btn"
                onClick={handleZoomIn}
                disabled={zoom >= MAX_ZOOM}
                aria-label="Zoom in"
              >
                [+]
              </button>
              <button
                type="button"
                className="pdf-btn"
                onClick={handleFit}
                aria-label="Fit to width"
              >
                [fit]
              </button>
              <button
                type="button"
                className="pdf-btn"
                onClick={handleDownload}
                aria-label="Download file"
              >
                [download]
              </button>
            </div>
          </div>

          {/* Canvas area */}
          <div className="pdf-canvas-area" ref={canvasAreaRef}>
            {Array.from({ length: numPages }, (_, i) => i + 1).map((pageNum) => (
              <canvas key={pageNum} ref={(el) => setCanvasRef(pageNum, el)} data-page={pageNum} />
            ))}
          </div>

          {/* Footer */}
          <div className="pdf-footer">
            <button
              type="button"
              className="pdf-btn"
              onClick={handlePrevPage}
              disabled={currentPage <= 1}
              aria-label="Previous page"
            >
              [&lt;&lt;]
            </button>
            <span className="pdf-page-info">
              page {currentPage} / {numPages}
            </span>
            <button
              type="button"
              className="pdf-btn"
              onClick={handleNextPage}
              disabled={currentPage >= numPages}
              aria-label="Next page"
            >
              [&gt;&gt;]
            </button>
          </div>
        </>
      )}
    </Modal>
  );
}

